proof:
method minArray(a: array<int>) returns (r:int)
  requires a.Length > 0
  ensures forall i :: 0 <= i < a.Length ==> r <= a[i]
  ensures exists i :: 0 <= i < a.Length && r == a[i]
{
  r:=a[0];
  var i:=1;
  while i<a.Length
    decreases a.Length - i // candidate
    invariant 0 <= i // candidate
    invariant i <= a.Length // candidate
    invariant forall j :: 0 <= j < i ==> r <= a[j] // candidate
    invariant forall i :: 0 <= i < i ==> r <= a[i] // candidate
    invariant exists i :: 0 <= i < a.Length && r == a[i] // candidate
  {
    if r>a[i]{
      r:=a[i];
    }
    i:=i+1;
  }
}

method Reverse(a: array<char>) returns (b: array<char>)
requires a.Length > 0
ensures a == old(a)
ensures b.Length == a.Length
ensures forall i :: 0 <= i < a.Length ==> b[i] == a[a.Length - i - 1]
{
	b := new char[a.Length];
	var i := 0;
	while i < a.Length
	  invariant 0 <= i <= a.Length // candidate
	  invariant forall j :: 0 <= j < i ==> b[j] == a[a.Length - j - 1] // candidate
	  decreases a.Length - i // candidate
	  invariant 0 <= i // candidate
	  invariant i <= a.Length // candidate
	  invariant b.Length == a.Length // candidate
	  invariant forall i :: 0 <= i < i ==> b[i] == a[i - i - 1] // candidate
	{
		b[i] := a[a.Length - i - 1];
		i := i + 1;
	}
}

method Main()
{
  var a := new char[]['s', 'k', 'r', 'o', 'w', 't', 'i'];
  var b := Reverse(a);
  print b[..];

  a := new char[]['!'];
  b := Reverse(a);
  print b[..], '\n';
}
